// Up to 3 photos per category (no video slot — unlike Hospitality's units, a category is a
// grouping concept, not a bookable thing worth a walkthrough video). image_url_1/2/3 now hold a
// pasted Google Drive share link (same "Ecommerce categories — photos" switch as Hospitality's
// unit photos/video, SETUP.md) rather than an uploaded file — handleEcomCategoryUpdate above
// accepts them as plain string PATCH fields, and engineMaybeSendEcomCategoryMedia below fetches
// each one's bytes with the same driveFileId/driveFetchFile helpers hospitalitySendUnitMedia uses.
// The upload/delete/serve routes and R2 binding (ECOM_CATEGORY_MEDIA) below are kept only for
// backward compatibility with any category that already had a file uploaded before this switch —
// nothing in the current frontend calls the upload endpoint anymore. R2 key extension isn't
// tracked separately in D1, so delete/replace try every extension validation could ever have
// accepted — an R2 delete on a nonexistent key is a harmless no-op.
const ECOM_CATEGORY_MEDIA_SLOTS={image1:'image_url_1', image2:'image_url_2', image3:'image_url_3'};
const ECOM_CATEGORY_MEDIA_MAX_BYTES=9*1024*1024;
const ECOM_CATEGORY_IMAGE_EXTS=['jpg','jpeg','png','webp','gif'];
function ecomCategoryMediaKey(clientId, categoryId, slot, ext){ return `ecomcat/${clientId}/${categoryId}/${slot}.${ext}`; }

async function handleEcomCategoryMediaUpload(request, env){
  const form=await request.formData().catch(()=>null);
  if(!form) return json({error:'multipart form data required'}, 400);
  const clientId=String(form.get('client_id')||'');
  const categoryId=form.get('category_id'), slot=form.get('slot'), file=form.get('file');
  if(!clientId||!categoryId||!slot||!file) return json({error:'client_id, category_id, slot and file required'}, 400);
  const column=ECOM_CATEGORY_MEDIA_SLOTS[slot];
  if(!column) return json({error:'Invalid slot'}, 400);
  const category=await findEcomCategory(env, categoryId);
  if(!category || String(category.client_id)!==clientId) return json({error:'Not found'}, 404);
  if(file.size>ECOM_CATEGORY_MEDIA_MAX_BYTES) return json({error:'File is too large — max 9 MB.'}, 400);
  const mime=(file.type||'').split(';')[0];
  if(!mime.startsWith('image/')) return json({error:'Category photos need an image file.'}, 400);
  const ext=(mime.split('/')[1]||'').replace(/[^a-z0-9]/gi,'').toLowerCase()||'jpg';
  const key=ecomCategoryMediaKey(clientId, categoryId, slot, ext);
  await env.ECOM_CATEGORY_MEDIA.put(key, await file.arrayBuffer(), {httpMetadata:{contentType:mime||'application/octet-stream'}});
  const url=`${env.WORKER_BASE_URL}/ecom/category-media/${key}`;
  await env.DB.prepare(`UPDATE ecom_categories SET ${column}=? WHERE id=?`).bind(url, Number(categoryId)).run();
  return json({ok:true, url, slot});
}
async function handleEcomCategoryMediaDelete(request, env){
  const body=await request.json().catch(()=>({}));
  const clientId=String(body.client_id||'');
  const {category_id, slot}=body;
  if(!clientId||!category_id||!slot) return json({error:'client_id, category_id and slot required'}, 400);
  const column=ECOM_CATEGORY_MEDIA_SLOTS[slot];
  if(!column) return json({error:'Invalid slot'}, 400);
  const category=await findEcomCategory(env, category_id);
  if(!category || String(category.client_id)!==clientId) return json({error:'Not found'}, 404);
  for(const ext of ECOM_CATEGORY_IMAGE_EXTS){ try{ await env.ECOM_CATEGORY_MEDIA.delete(ecomCategoryMediaKey(clientId, category_id, slot, ext)); }catch(e){} }
  await env.DB.prepare(`UPDATE ecom_categories SET ${column}=NULL WHERE id=?`).bind(Number(category_id)).run();
  return json({ok:true});
}
// Public, no session — same trust model as handleHospitalityMediaServe (Chatwoot/WhatsApp's own
// media fetch and a plain <img> tag can't send an Authorization header; the key itself, keyed by
// client+category+slot, isn't guessable).
async function handleEcomCategoryMediaServe(env, key){
  if(!key) return json({error:'Not found'}, 404);
  const obj=await env.ECOM_CATEGORY_MEDIA.get(key);
  if(!obj) return json({error:'Not found'}, 404);
  const headers=new Headers();
  obj.writeHttpMetadata(headers);
  headers.set('etag', obj.httpEtag);
  headers.set('Cache-Control','public, max-age=86400');
  return new Response(obj.body, {headers});
}

/* ════════════════════════════════════════════════════════════════════════════════════════════════
   BUSINESS SERVICES MODULE
   D1-backed CRUD for service centres (CSC/Akshaya-style). Services behave like Ecom products
   with fee, turnaround_time, required_docs, appointment_required, service_type, government_url.
   Categories have up to 3 photos (image_url_1/2/3) — same link-paste model as Ecom categories.
   Client-id-based auth — same trust model as /ecom/*.
   business-services.html embeds as an iframe in dashboard.html.
   ════════════════════════════════════════════════════════════════════════════════════════════════ */

const BS_CLIENT_READ_FIELDS=['Id','client_name','bot_config'];
const BS_CLIENT_WRITE_FIELDS=['bot_config'];

let _bsSchemaEnsured=false;
async function bsEnsureSchema(env){
  if(_bsSchemaEnsured)return;
  await env.DB.batch([
    env.DB.prepare(`CREATE TABLE IF NOT EXISTS bs_categories (id INTEGER PRIMARY KEY AUTOINCREMENT,client_id INTEGER NOT NULL,name TEXT NOT NULL,description TEXT,image_url_1 TEXT,image_url_2 TEXT,image_url_3 TEXT,created_at TEXT NOT NULL)`),
    env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_bs_categories_client ON bs_categories(client_id)`),
    env.DB.prepare(`CREATE TABLE IF NOT EXISTS bs_services (id INTEGER PRIMARY KEY AUTOINCREMENT,client_id INTEGER NOT NULL,category_id INTEGER,name TEXT NOT NULL,description TEXT,fee TEXT,turnaround_time TEXT,required_docs TEXT,appointment_required INTEGER NOT NULL DEFAULT 0,service_type TEXT,government_url TEXT,image_url_1 TEXT,image_url_2 TEXT,image_url_3 TEXT,pdf_url TEXT,status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL)`),
    env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_bs_services_client ON bs_services(client_id)`),
    env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_bs_services_category ON bs_services(client_id,category_id)`),
  ]);
  _bsSchemaEnsured=true;
}

