// Currencies — for the Document modal's Currency field (a `<datalist>`, not a hard `<select>`, so
// it still degrades to a plain text input if ERPNext isn't connected — see accounting.html).
async function handleErpnextCurrenciesList(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const c=await getClientById(env, payload.cid);
  if(!c || !erpnextConfigured(c)) return json({error:'ERPNext is not connected for this account — add your Frappe Cloud site URL and API key/secret in the ⚙️ ERPNext tab.'}, 400);
  const fields=encodeURIComponent(JSON.stringify(['name']));
  const filters=encodeURIComponent(JSON.stringify([['enabled','=',1]]));
  const r=await erpnextFetch(c, `/api/resource/Currency?fields=${fields}&filters=${filters}&limit_page_length=200&order_by=name asc`);
  const data=await r.json().catch(()=>({}));
  if(!r.ok) return json({error:erpnextErrorMessage(data, r.status)}, 502);
  return json({list:data?.data||[]});
}

// Account picker, shared by the Document modal's Debtors Account field and the Expense Entry
// modal's Expense Account / Paid From Account fields. ERPNext's Account doctype is company-scoped,
// so this is only useful once a Company has been picked (accounting.html re-fetches on company
// change); ?company= is optional here purely so the route doesn't hard-fail before that.
// Defaults to account_type=Receivable (the Debtors picker's original, only behavior) when neither
// ?account_type= nor ?root_type= is passed, so that existing call site keeps working unchanged;
// the Expense Entry modal instead passes ?root_type=Expense (every Account has a root_type —
// Asset/Liability/Income/Expense/Equity — a more reliable filter than account_type, which is often
// left blank on plain ledger accounts) or ?root_type=Asset for the Paid From picker.
async function handleErpnextAccountsList(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const c=await getClientById(env, payload.cid);
  if(!c || !erpnextConfigured(c)) return json({error:'ERPNext is not connected for this account — add your Frappe Cloud site URL and API key/secret in the ⚙️ ERPNext tab.'}, 400);
  const url=new URL(request.url);
  const company=(url.searchParams.get('company')||'').trim();
  const rootType=(url.searchParams.get('root_type')||'').trim();
  const accountType=(url.searchParams.get('account_type')||(rootType?'':'Receivable')).trim();
  const fields=encodeURIComponent(JSON.stringify(['name','account_name','company','account_type','root_type']));
  const filterList=[];
  if(accountType) filterList.push(['account_type','=',accountType]);
  if(rootType) filterList.push(['root_type','=',rootType]);
  if(company) filterList.push(['company','=',company]);
  const filters=encodeURIComponent(JSON.stringify(filterList));
  const r=await erpnextFetch(c, `/api/resource/Account?fields=${fields}&filters=${filters}&limit_page_length=200&order_by=account_name asc`);
  const data=await r.json().catch(()=>({}));
  if(!r.ok) return json({error:erpnextErrorMessage(data, r.status)}, 502);
  return json({list:data?.data||[]});
}

// Sends an already-generated document PDF (built client-side, same jsPDF doc as the download
// button) as a Resend email attachment — the Worker never generates the PDF itself, just relays
// the caller's own bytes, since accounting.html's PDF layout has no server-side equivalent.
async function handleAccountingDocumentSendEmail(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const body=await request.json().catch(()=>({}));
  if(!body.id) return json({error:'id required'}, 400);
  if(!body.to) return json({error:'to required'}, 400);
  if(!body.pdf_base64) return json({error:'pdf_base64 required'}, 400);
  const doc=await findAccountingDocument(env, body.id);
  if(!doc || String(doc.client_id)!==String(payload.cid)) return json({error:'Not found'}, 404);
  const c=await getClientById(env, payload.cid);
  const typeLabel={quotation:'Quotation', invoice:'Invoice', receipt:'Receipt'}[doc.type]||'Document';
  const subject=body.subject||`${typeLabel} from ${c?.client_name||'us'}`;
  const html=body.html||`<p>Please find your ${typeLabel.toLowerCase()} attached.</p>`;
  const result=await sendClientResendEmail(c, {
    to:body.to, subject, html,
    attachments:[{filename:String(body.filename||`${typeLabel}.pdf`), content:String(body.pdf_base64)}]
  });
  if(!result.ok) return json({error:result.error}, result.error==='Connect Resend first.'||result.error==='Set a from-email first.'?400:502);
  if(doc.status==='draft') await env.DB.prepare(`UPDATE accounting_documents SET status='sent' WHERE id=?`).bind(doc.id).run();
  return json({ok:true});
}

/* ── Financial Planning module (frontend/accounting.html — "💰 Financial Planning" tab,
   SETUP.md "Financial Planning module") ──
   Recurring revenue (fp_customers → fp_expected_dues → fp_collections) and expense tracking
   (fp_expense_templates, auto-booked monthly, vs. one-off fp_expenses) — migrations/0015_financial_planning.sql.
   Distinct from the existing "👤 Customers" tab (a live ERPNext passthrough with zero local
   storage) — fp_customers is this app's own recurring-billing record, independent of whether
   ERPNext is even connected. Every route below is session-gated and checks row ownership against
   payload.cid the same way every other Accounting/Hospitality route in this file does. */

function fpClampBillingDay(n){ const v=parseInt(n)||1; return Math.max(1, Math.min(28, v)); }
function fpCustomerOut(r){ return {...r, Id:r.id}; }

async function findFpCustomer(env, id){
  return await env.DB.prepare(`SELECT * FROM fp_customers WHERE id=?`).bind(Number(id)).first();
}
// Every write to fp_customers/fp_expense_templates upserts this row so the monthly cron and
// reminder sweep (below) only ever scan clients that actually have Financial Planning data,
// instead of a full CLIENTS table paginate every tick — same "only scan opted-in clients" pattern
// as review_config.
async function fpEnsureConfigRow(env, clientId){
  await env.DB.prepare(`INSERT INTO fp_config (client_id, enabled, reminders_enabled, updated_at) VALUES (?,1,1,?)
    ON CONFLICT(client_id) DO NOTHING`).bind(Number(clientId), new Date().toISOString()).run();
}

