    csm_owner:String(body.csm_owner||'').trim().slice(0,140),
    gstin:body.gstin?String(body.gstin).trim().slice(0,15):null,
    state_code:body.state_code?String(body.state_code).trim().slice(0,50).toUpperCase():null,
