  await env.DB.prepare(`DELETE FROM fp_customers WHERE id=?`).bind(Number(body.id)).run();
  await env.DB.prepare(`DELETE FROM fp_expected_dues WHERE customer_id=?`).bind(Number(body.id)).run();
